// Definition: 1 only if corresponding bits differ
unsigned int A = 0b11001100; // 204
unsigned int B = 0b10101010; // 170
unsigned int C = A ^ B;      // 0b01100110 (102)

// Use Case 1: Toggling/Flipping a specific bit (Bit 3)
int status = 0b10000;
int toggle_mask = 1 << 3;
status ^= toggle_mask; // status is now 0b11000

// Use Case 2: Symmetric Encryption (XOR Cipher)
char key = 0xAF;
char data = 'H';
char encrypted = data ^ key;
char original = encrypted ^ key; // original == data
